-- Add age-10 public children's questions without changing existing questions or responses.
-- Corrected ambiguous riddles; avoids repeating 20 already seeded questions.
-- Safe to re-run on an existing database, scoped to the public children's category.
WITH source AS (
  SELECT * FROM jsonb_to_recordset($children_seed$
[{"q":"ما عاصمة المملكة العربية السعودية؟","o":["الرياض","جدة","مكة المكرمة","الدمام"],"a":1},{"q":"ما لون السماء غالبًا في يوم صافٍ؟","o":["الأخضر","الأزرق","البنفسجي","البرتقالي"],"a":2},{"q":"كم عدد فصول السنة المعتادة؟","o":["3 فصول","5 فصول","4 فصول","6 فصول"],"a":3},{"q":"ما أسرع حيوان بري؟","o":["الأسد","الحصان","النعامة","الفهد الصياد"],"a":4},{"q":"كم عدد القارات وفق التقسيم الجغرافي الشائع؟","o":["7 قارات","5 قارات","6 قارات","8 قارات"],"a":1},{"q":"ما أكبر محيط في العالم؟","o":["المحيط الأطلسي","المحيط الهادئ","المحيط الهندي","المحيط المتجمد الشمالي"],"a":2},{"q":"ما عاصمة مصر؟","o":["الإسكندرية","الأقصر","القاهرة","أسوان"],"a":3},{"q":"من أي جهة تشرق الشمس؟","o":["الغرب","الشمال","الجنوب","الشرق"],"a":4},{"q":"كم عدد الأسنان الدائمة عادة لدى الشخص البالغ، بما فيها ضروس العقل؟","o":["32 سنًا","20 سنًا","24 سنًا","28 سنًا"],"a":1},{"q":"ما أكبر حيوان يعيش على الأرض حاليًا؟","o":["الفيل الأفريقي","الحوت الأزرق","الزرافة","القرش الأبيض"],"a":2},{"q":"ما اللون الغالب على أوراق النباتات الخضراء؟","o":["الأحمر","الأسود","الأخضر","البنفسجي"],"a":3},{"q":"ما الغاز الذي تحتاجه خلايا الإنسان للتنفس؟","o":["الهيليوم","الهيدروجين","النيون","الأكسجين"],"a":4},{"q":"كم عدد أصابع اليدين معًا عند معظم الناس؟","o":["10 أصابع","8 أصابع","12 إصبعًا","6 أصابع"],"a":1},{"q":"كم دقيقة في الساعة الواحدة؟","o":["50 دقيقة","60 دقيقة","100 دقيقة","30 دقيقة"],"a":2},{"q":"ما الشيء الذي كلما أخذت منه كبر؟","o":["الكتاب","القلم","الحفرة","الطاولة"],"a":3},{"q":"ما الآلة التي لها مفاتيح لكنها لا تفتح الأبواب؟","o":["الدراجة","الساعة","المرآة","البيانو"],"a":4},{"q":"ما الشيء الذي نقول إنه يمضي دون أرجل؟","o":["الوقت","الكرسي","الصخرة","النافذة"],"a":1},{"q":"كان لديك 5 تفاحات وأكلت 2؛ كم تفاحة بقيت؟","o":["2 تفاحتان","3 تفاحات","5 تفاحات","7 تفاحات"],"a":2},{"q":"ما الشيء الذي يكتب ولا يستطيع قراءة ما كتب؟","o":["المعلم","التلميذ","القلم","الأم"],"a":3},{"q":"ما الشيء الذي يزداد بالتعلّم والممارسة؟","o":["العطش","الجوع","الظلام","المعرفة"],"a":4},{"q":"ما الشيء الذي يمكن كسره دون لمسه؟","o":["الوعد","الكوب","النافذة","الحجر"],"a":1},{"q":"ما الجهاز الذي ينقل إلينا صوت شخص بعيد؟","o":["الوسادة","الهاتف","الحقيبة","المسطرة"],"a":2},{"q":"ما الشيء الذي له عين ولا يرى ويُستخدم في الخياطة؟","o":["المقص","الخيط","الإبرة","القماش"],"a":3},{"q":"ما الشيء الذي له أسنان ولا يعض؟","o":["الأسد","التمساح","القرش","المشط"],"a":4},{"q":"ما الشيء الذي يظهر في المرآة ويتحرك معك؟","o":["انعكاس صورتك","شخص آخر","القمر","الظل على الحائط"],"a":1},{"q":"شيء كلما مشيت نحوه ابتعد عنك في الأفق، ما هو؟","o":["الحائط","الأفق","المقعد","الباب"],"a":2},{"q":"ما الذي له وجه وعقربان ولكنه لا يتكلم؟","o":["القطة","الإنسان","الساعة","السيارة"],"a":3},{"q":"ما الشيء الذي تستطيع أن ترى من خلاله وهو صلب وشفاف؟","o":["الخشب","الحجر","الحديد","الزجاج"],"a":4},{"q":"ما الشيء الذي ينكسر إذا قلت اسمه؟","o":["الصمت","الضوء","البحر","الجبل"],"a":1},{"q":"ما الذي يبدأ طويلًا ثم يقصر مع استعماله في الكتابة؟","o":["الدفتر","قلم الرصاص","المسطرة","الكتاب"],"a":2},{"q":"ما الشيء الذي له مدن وأنهار لكنه ليس أرضًا حقيقية؟","o":["السجادة","النافذة","الخريطة","السبورة"],"a":3},{"q":"ما الشيء الذي يرتفع في السماء إذا ملأته بالهواء؟","o":["الحجر","الكتاب","المسمار","البالون"],"a":4},{"q":"ما الشيء الذي يأخذ شكل الوعاء الذي يُسكب فيه؟","o":["الماء","الخشب","الحديد","الزجاج الصلب"],"a":1},{"q":"ما أكبر كوكب في المجموعة الشمسية؟","o":["الأرض","المشتري","عطارد","المريخ"],"a":2},{"q":"ما مصدر الضوء والحرارة الرئيس للأرض؟","o":["القمر","النجوم البعيدة","الشمس","البرق"],"a":3},{"q":"ما الغاز الذي تطلقه النباتات الخضراء عادة أثناء البناء الضوئي؟","o":["النيتروجين","الهيليوم","الميثان","الأكسجين"],"a":4},{"q":"ماذا يحدث للماء السائل عندما يغلي؟","o":["يتحول إلى بخار","يتحول إلى حجر","يتحول إلى خشب","يختفي من الوجود"],"a":1},{"q":"ما الحيوان البحري الذي يتنفس الهواء بالرئتين؟","o":["القرش","الحوت","الأخطبوط","سمكة التونة"],"a":2},{"q":"ما اسم الجسم الذي يجذب الحديد بالمغناطيسية؟","o":["الإسفنجة","الورقة","المغناطيس","الزجاجة"],"a":3},{"q":"ماذا تسمى صغار الضفدع بعد الفقس؟","o":["اليرقات النحلية","الكتاكيت","الأشبال","الشراغيف"],"a":4},{"q":"أي كوكب يكمل دورة حول الشمس في أقصر مدة؟","o":["عطارد","نبتون","زحل","المشتري"],"a":1},{"q":"كم ناتج 9 × 8؟","o":["64","72","81","78"],"a":2},{"q":"كم ناتج 100 ÷ 4؟","o":["20","40","25","50"],"a":3},{"q":"كم ناتج 15 + 28؟","o":["42","33","53","43"],"a":4},{"q":"كم ناتج 60 − 18؟","o":["42","48","38","32"],"a":1},{"q":"ما نصف العدد 80؟","o":["20","40","60","30"],"a":2},{"q":"كم ناتج 12 × 7؟","o":["72","96","84","74"],"a":3},{"q":"ما ربع العدد 100؟","o":["20","50","75","25"],"a":4},{"q":"كم ناتج 45 + 55؟","o":["100","90","110","95"],"a":1},{"q":"كم ناتج 11 × 11؟","o":["111","121","101","131"],"a":2},{"q":"كم ناتج 96 ÷ 8؟","o":["10","14","12","16"],"a":3},{"q":"ما أطول نهر في قارة أفريقيا؟","o":["الدانوب","التايمز","السين","النيل"],"a":4},{"q":"ما أكبر قارة من حيث المساحة؟","o":["آسيا","أفريقيا","أوروبا","أستراليا"],"a":1},{"q":"من اشتهر بتطوير المصباح الكهربائي المتوهج العملي تجاريًا؟","o":["إسحاق نيوتن","توماس إديسون","ألبرت أينشتاين","غاليليو"],"a":2},{"q":"أي لغة يتحدث بها أكبر عدد من الناس كلغة أم؟","o":["الإيطالية","اليونانية","الصينية المندرينية","السويدية"],"a":3},{"q":"كم عدد ألوان قوس قزح في التصنيف المدرسي الشائع؟","o":["5 ألوان","8 ألوان","10 ألوان","7 ألوان"],"a":4},{"q":"ما أكبر دولة في العالم من حيث المساحة؟","o":["روسيا","مصر","اليابان","أستراليا"],"a":1},{"q":"من أول إنسان سافر إلى الفضاء الخارجي؟","o":["نيل أرمسترونغ","يوري غاغارين","ألبرت أينشتاين","إسحاق نيوتن"],"a":2},{"q":"ما الحيوان الذي يظهر على شعار أستراليا إلى جانب طائر الإيمو؟","o":["الفيل","الدب القطبي","الكنغر","الأسد"],"a":3},{"q":"ما أكبر صحراء حارة في العالم؟","o":["صحراء جوبي","صحراء أتاكاما","صحراء ثار","الصحراء الكبرى"],"a":4},{"q":"ما أعلى جبل فوق مستوى سطح البحر؟","o":["إيفرست","كيلمنجارو","فوجي","أحد"],"a":1},{"q":"ما الشيء الذي له أوراق لكنه ليس شجرة؟","o":["الكرسي","الكتاب","المفتاح","المصباح"],"a":2},{"q":"ما الشيء الذي له رقبة لكنه بلا رأس؟","o":["الحصان","العصفور","الزجاجة","الإنسان"],"a":3},{"q":"ما الشيء الذي يجفف غيره ويصبح هو أكثر بللًا؟","o":["المروحة","الشمس","المكواة","المنشفة"],"a":4},{"q":"ما الشيء الذي ينمو من بذرة إلى شجرة دون أن يمشي؟","o":["النبات","الطائر","السمك","القط"],"a":1}]
$children_seed$::jsonb) AS s(q text,o jsonb,a integer)
),
owner_user AS (
  SELECT id,display_name FROM users WHERE owner AND NOT archived ORDER BY id LIMIT 1
),
inserted AS (
  INSERT INTO questions (
    company_id,category,priority,question,answer1,answer2,answer3,answer4,
    option_count,correct_answer,points,active,created_by
  )
  SELECT NULL,'أسئلة للأطفال',2,s.q,
    s.o->>0,s.o->>1,s.o->>2,s.o->>3,4,s.a,1,TRUE,u.id
  FROM source s CROSS JOIN owner_user u
  WHERE NOT EXISTS (
    SELECT 1 FROM questions old WHERE old.company_id IS NULL
      AND old.category='أسئلة للأطفال' AND old.question=s.q
  )
  RETURNING id,created_by,category,priority,question,
    answer1,answer2,answer3,answer4,correct_answer,points,active
)
INSERT INTO audit_events (
  actor_id,actor_name,scope,company_id,action,target_type,
  target_id,before_value,after_value
)
SELECT i.created_by,u.display_name,'public',NULL,'question.create',
  'question',i.id,NULL,
  jsonb_build_object('category',i.category,'priority',i.priority,
    'question',i.question,
    'options',jsonb_build_array(i.answer1,i.answer2,i.answer3,i.answer4),
    'correctAnswer',i.correct_answer,'points',i.points,'active',i.active)
FROM inserted i JOIN owner_user u ON u.id=i.created_by;
